    /// Secure Socket Layer (SSL) properties that apply when Amazon Quick Sight connects to your underlying source. DisableSsl -&gt; (boolean) A Boolean option to control whether SSL should be disabled. Shorthand Syntax: DisableSsl=boolean JSON Syntax: { "DisableSsl": true|false }
    /// </summary>
    [CliOption("--ssl-properties")]
